def voice_clone(credential_id, voice_id, file, text=None, is_user_provided_content=None, **_extra):
    import json, os, datetime, time, uuid, urllib.parse, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # ---- helpers
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_key(dt):
        return dt.strftime("%Y-%m")

    def _maybe_reset_monthly_counters(cred_row):
        # Reset counters if last_used_at is from a different calendar month.
        lu = _parse_dt(cred_row.get("last_used_at"))
        if lu is None:
            return
        if _month_key(lu) != _month_key(now_dt):
            cred_row["current_month_requests"] = 0
            cred_row["current_month_cost_usd_estimate"] = 0.0

    def _is_url(s):
        try:
            u = urllib.parse.urlparse(s)
            return u.scheme in ("http", "https") and bool(u.netloc)
        except Exception:
            return False

    def _gen_ulid_like(prefix):
        # Not a real ULID, but stable prefix used by datastore examples.
        return f"{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{uuid.uuid4().hex[:14]}".replace("-", "")

    def _request_log(endpoint, credential_id_val, status, error_code=None, error_message=None, request_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return
        logs.append({
            "id": _gen_ulid_like("mmx_log"),
            "endpoint": endpoint,
            "credential_id": credential_id_val,
            "request_id": request_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # ---- validate inputs
    if not isinstance(credential_id, str) or not credential_id.strip():
        _request_log("voice_clone", None, "error", "VALIDATION_ERROR", "credential_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "credential_id must be a non-empty string")
    if not isinstance(voice_id, str) or not voice_id.strip():
        _request_log("voice_clone", credential_id, "error", "VALIDATION_ERROR", "voice_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "voice_id must be a non-empty string")
    if not isinstance(file, str) or not file.strip():
        _request_log("voice_clone", credential_id, "error", "VALIDATION_ERROR", "file must be a non-empty string")
        return _err("VALIDATION_ERROR", "file must be a non-empty string")
    if text is not None and not isinstance(text, str):
        _request_log("voice_clone", credential_id, "error", "VALIDATION_ERROR", "text must be a string when provided")
        return _err("VALIDATION_ERROR", "text must be a string when provided")
    if is_user_provided_content is None:
        is_user_provided_content_val = False
    else:
        if not isinstance(is_user_provided_content, bool):
            _request_log("voice_clone", credential_id, "error", "VALIDATION_ERROR", "is_user_provided_content must be boolean when provided")
            return _err("VALIDATION_ERROR", "is_user_provided_content must be boolean when provided")
        is_user_provided_content_val = is_user_provided_content

    # ---- load store
    creds = _load("api_credentials.json")
    voices = _load("voices.json")
    genreqs = _load("generation_requests.json")
    assets = _load("media_assets.json")

    if not isinstance(creds, list) or not isinstance(voices, list) or not isinstance(genreqs, list) or not isinstance(assets, list):
        _request_log("voice_clone", credential_id, "error", "CONFLICT", "datastore is not initialized correctly")
        return _err("CONFLICT", "datastore is not initialized correctly")

    # ---- authenticate/resolve credential
    # Credential parameter can be either id or api_key "client-visible value".
    cred = None
    for c in creds:
        if isinstance(c, dict) and (c.get("id") == credential_id or c.get("api_key") == credential_id):
            cred = c
            break
    if cred is None:
        # Search any usable combination if caller provided something unusable; treat as UNAUTHORIZED.
        active_any = next((c for c in creds if isinstance(c, dict) and c.get("status") == "active"), None)
        _request_log("voice_clone", None, "error", "UNAUTHORIZED", "credential not recognized")
        return _err("UNAUTHORIZED", "credential not recognized")

    # Enforce credential active rule
    if cred.get("status") != "active":
        _request_log("voice_clone", cred.get("id"), "error", "UNAUTHORIZED", "credential is not active")
        return _err("UNAUTHORIZED", "credential is not active")

    # ---- quota enforcement (COST WARNING tool)
    _maybe_reset_monthly_counters(cred)
    monthly_request_quota = cred.get("monthly_request_quota")
    monthly_cost_usd_limit = cred.get("monthly_cost_usd_limit")
    cur_reqs = cred.get("current_month_requests")
    cur_cost = cred.get("current_month_cost_usd_estimate")

    if not isinstance(monthly_request_quota, int) or monthly_request_quota < 0:
        _request_log("voice_clone", cred.get("id"), "error", "CONFLICT", "credential monthly_request_quota invalid")
        return _err("CONFLICT", "credential monthly_request_quota invalid")
    if not isinstance(monthly_cost_usd_limit, (int, float)) or monthly_cost_usd_limit < 0:
        _request_log("voice_clone", cred.get("id"), "error", "CONFLICT", "credential monthly_cost_usd_limit invalid")
        return _err("CONFLICT", "credential monthly_cost_usd_limit invalid")
    if not isinstance(cur_reqs, int) or cur_reqs < 0:
        cur_reqs = 0
        cred["current_month_requests"] = 0
    if not isinstance(cur_cost, (int, float)) or cur_cost < 0:
        cur_cost = 0.0
        cred["current_month_cost_usd_estimate"] = 0.0

    # Heuristic cost estimate for voice clone
    cost_usd_estimate = 0.08
    if cur_reqs + 1 > monthly_request_quota:
        _request_log("voice_clone", cred.get("id"), "error", "QUOTA_EXCEEDED", "monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "monthly request quota exceeded")
    if (cur_cost + float(cost_usd_estimate)) > float(monthly_cost_usd_limit):
        _request_log("voice_clone", cred.get("id"), "error", "QUOTA_EXCEEDED", "monthly cost limit exceeded")
        return _err("QUOTA_EXCEEDED", "monthly cost limit exceeded")

    # ---- create generation request row with status queued
    req_id = _gen_ulid_like("mmx_req")
    req_row = {
        "id": req_id,
        "credential_id": cred.get("id"),
        "tool_name": "voice_clone",
        "status": "queued",
        "vendor_request_id": None,
        "model": None,
        "prompt": None,
        "aspect_ratio": None,
        "voice_id": voice_id,  # base voice id
        "input_file": file,
        "input_is_url": bool(_is_url(file)),
        "text": text,
        "is_user_provided_content": bool(is_user_provided_content_val),
        "request_payload": {
            "credential_id": credential_id,
            "voice_id": voice_id,
            "file": file,
            "text": text,
            "is_user_provided_content": is_user_provided_content_val
        },
        "response_payload": None,
        "error_message": None,
        "cost_usd_estimate": float(cost_usd_estimate),
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    genreqs.append(req_row)
    _save("generation_requests.json", genreqs)

    # ---- upsert a voice row for the cloned voice (origin tenant_cloned)
    # Deterministic external id derived from request id to be idempotent-ish on retries.
    cloned_external_id = "cln_" + hashlib.sha256(req_id.encode("utf-8")).hexdigest()[:16]
    v_row = None
    for v in voices:
        if isinstance(v, dict) and v.get("credential_id") == cred.get("id") and v.get("external_minimax_voice_id") == cloned_external_id:
            v_row = v
            break

    if v_row is None:
        v_row = {
            "id": _gen_ulid_like("mmx_vce"),
            "credential_id": cred.get("id"),
            "external_minimax_voice_id": cloned_external_id,
            "display_name": f"Cloned voice {cloned_external_id}",
            "voice_type": "voice_cloning",
            "origin": "tenant_cloned",
            "language": None,
            "gender": None,
            "status": "creating",
            "metadata": {
                "base_voice_id": voice_id,
                "source_file": file
            },
            "created_at": now,
            "updated_at": now
        }
        voices.append(v_row)
    else:
        # Transition to creating if allowed
        cur_status = v_row.get("status")
        if cur_status in ("failed", "available", "disabled"):
            # enforce lifecycle transitions
            allowed = {
                "creating": ["available", "failed"],
                "available": ["disabled"],
                "failed": ["creating", "disabled"],
                "disabled": ["available"]
            }
            if cur_status != "creating":
                if "creating" in allowed.get(cur_status, []):
                    v_row["status"] = "creating"
                else:
                    _request_log("voice_clone", cred.get("id"), "error", "INVALID_TRANSITION", f"cannot transition voice from {cur_status} to creating", request_id=req_id)
                    return _err("INVALID_TRANSITION", f"cannot transition voice from {cur_status} to creating")
        v_row["origin"] = "tenant_cloned"
        v_row["voice_type"] = "voice_cloning"
        v_row["metadata"] = dict(v_row.get("metadata") or {})
        v_row["metadata"].update({"base_voice_id": voice_id, "source_file": file})
        v_row["updated_at"] = now
    _save("voices.json", voices)

    # ---- transition request queued -> running
    req_row["status"] = "running"
    req_row["started_at"] = now
    req_row["updated_at"] = now
    _save("generation_requests.json", genreqs)

    # ---- "upstream" simulated result (offline)
    # Fail for obviously bad formats some vendors reject; otherwise succeed.
    lower = file.lower()
    unacceptable_ext = (lower.endswith(".flac") or lower.endswith(".m4a") or lower.endswith(".aac"))
    succeeded = not unacceptable_ext

    if succeeded:
        # request running -> succeeded
        req_row["status"] = "succeeded"
        req_row["finished_at"] = now
        req_row["response_payload"] = {
            "cloned_voice_id": cloned_external_id,
            "demo_generated": bool(text)
        }
        req_row["updated_at"] = now

        # voice creating -> available
        if v_row.get("status") == "creating":
            v_row["status"] = "available"
        v_row["updated_at"] = now

        # create media asset for optional demo audio
        demo_asset = None
        if text:
            demo_asset = {
                "id": _gen_ulid_like("mmx_ast"),
                "credential_id": cred.get("id"),
                "request_id": req_id,
                "role": "output",
                "media_type": "audio",
                "format": "mp3",
                "storage": "remote_url",
                "local_path": None,
                "remote_url": f"https://cdn.local/minimax/demo/{req_id}.mp3",
                "byte_size": None,
                "duration_ms": None,
                "sha256": None,
                "status": "available",
                "created_at": now,
                "updated_at": now
            }
            assets.append(demo_asset)

        # increment quota counters on success
        cred["current_month_requests"] = int(cred.get("current_month_requests") or 0) + 1
        cred["current_month_cost_usd_estimate"] = float(cred.get("current_month_cost_usd_estimate") or 0.0) + float(cost_usd_estimate)
        cred["last_used_at"] = now
        cred["updated_at"] = now

        _save("api_credentials.json", creds)
        _save("voices.json", voices)
        _save("media_assets.json", assets)
        _save("generation_requests.json", genreqs)

        _request_log("voice_clone", cred.get("id"), "ok", request_id=req_id)
        return {
            "generation_request": req_row,
            "voice": v_row,
            "demo_media_asset": demo_asset
        }
    else:
        # request running -> failed
        req_row["status"] = "failed"
        req_row["finished_at"] = now
        req_row["error_message"] = "Unsupported audio format for voice cloning; provide wav or mp3."
        req_row["response_payload"] = {"error": "unsupported_format"}
        req_row["updated_at"] = now

        # voice creating -> failed
        if v_row.get("status") == "creating":
            v_row["status"] = "failed"
        v_row["updated_at"] = now

        # increment quota counters on failure as well
        cred["current_month_requests"] = int(cred.get("current_month_requests") or 0) + 1
        cred["current_month_cost_usd_estimate"] = float(cred.get("current_month_cost_usd_estimate") or 0.0) + float(cost_usd_estimate)
        cred["last_used_at"] = now
        cred["updated_at"] = now

        _save("api_credentials.json", creds)
        _save("voices.json", voices)
        _save("generation_requests.json", genreqs)

        _request_log("voice_clone", cred.get("id"), "error", "CONFLICT", req_row["error_message"], request_id=req_id)
        return _err("CONFLICT", req_row["error_message"], generation_request=req_row, voice=v_row)

def play_audio(input_file_path, is_url=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{uuid.uuid4().hex[:12]}"

    def _log(status, credential_id_val=None, error_code=None, error_message=None, asset_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("mmx_log"),
            "endpoint": "play_audio",
            "credential_id": credential_id_val,
            "asset_id": asset_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(input_file_path, str) or not input_file_path.strip():
        _log("error", None, "VALIDATION_ERROR", "input_file_path must be a non-empty string")
        return _err("VALIDATION_ERROR", "input_file_path must be a non-empty string")
    if is_url is not None and not isinstance(is_url, bool):
        _log("error", None, "VALIDATION_ERROR", "is_url must be boolean when provided")
        return _err("VALIDATION_ERROR", "is_url must be boolean when provided")

    p = input_file_path.strip()
    want_url = is_url if isinstance(is_url, bool) else (p.startswith("http://") or p.startswith("https://"))

    assets = _load("media_assets.json")
    if not isinstance(assets, list):
        _log("error", None, "CONFLICT", "media_assets datastore unavailable")
        return _err("CONFLICT", "media_assets datastore unavailable")

    # Resolve asset per business rule:
    # - must be media_type='audio'
    # - format in ('wav','mp3')
    # - status='available'
    # - match by local_path if is_url=false, or by remote_url if is_url=true
    match = None
    for a in assets:
        if not isinstance(a, dict):
            continue
        if a.get("media_type") != "audio":
            continue
        if a.get("format") not in ("wav", "mp3"):
            continue
        if a.get("status") != "available":
            continue

        if want_url:
            if a.get("storage") != "remote_url":
                continue
            if isinstance(a.get("remote_url"), str) and a.get("remote_url") == p:
                match = a
                break
        else:
            # Treat any non-http(s) "path-like" as local-path match, including s3:// per audit expectation.
            if a.get("storage") != "local":
                continue
            if isinstance(a.get("local_path"), str) and a.get("local_path") == p:
                match = a
                break

    if not match:
        # Determine whether it's a validation error (unsupported type) vs not-found
        # If the caller is trying to play something with non-audio extension, treat as VALIDATION_ERROR.
        lower = p.lower()
        ext = lower.rsplit(".", 1)[-1] if "." in lower else ""
        if ext and ext not in ("wav", "mp3"):
            _log("error", None, "VALIDATION_ERROR", "Only WAV and MP3 audio are supported for playback")
            return _err("VALIDATION_ERROR", "Only WAV and MP3 audio are supported for playback")
        _log("error", None, "NOT_FOUND", "play_audio requires an available audio media_asset whose local_path/remote_url matches the provided input_file_path")
        return _err("NOT_FOUND", "play_audio requires an available audio media_asset whose local_path/remote_url matches the provided input_file_path")

    # Attempt access: local file existence check (remote_url cannot be fetched offline, so we only validate presence)
    if want_url:
        # For remote URLs we can't truly "access" offline; consider it playable if it's in the catalog as available.
        _log("success", match.get("credential_id"), None, None, asset_id=match.get("id"))
        return {
            "played": True,
            "storage": "remote_url",
            "location": match.get("remote_url"),
            "asset": match
        }
    else:
        lp = match.get("local_path")
        if not isinstance(lp, str) or not lp:
            _log("error", match.get("credential_id"), "CONFLICT", "media_asset storage=local but local_path is missing", asset_id=match.get("id"))
            return _err("CONFLICT", "media_asset storage=local but local_path is missing", asset_id=match.get("id"))
        if not os.path.exists(lp):
            _log("error", match.get("credential_id"), "NOT_FOUND", "local audio file does not exist on disk", asset_id=match.get("id"))
            return _err("NOT_FOUND", "local audio file does not exist on disk", asset_id=match.get("id"), local_path=lp)

        _log("success", match.get("credential_id"), None, None, asset_id=match.get("id"))
        return {
            "played": True,
            "storage": "local",
            "location": lp,
            "asset": match
        }

def generate_video(credential_id, prompt, model=None, input_file=None, input_is_url=None, is_user_provided_content=None, **_extra):
    import json, os, datetime, time, base64, hashlib, random, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_creds = _load("api_credentials.json")
    gen_reqs = _load("generation_requests.json")
    assets = _load("media_assets.json")

    # Helpers
    def _log(cred_id, status, error_code=None, error_message=None, request_id=None):
        # Observable dynamics: if no dedicated request-log collection exists, store audit rows on generation_requests metadata is not allowed.
        # Best-effort: append an audit entry into generation_requests.json side-channel file if present; otherwise do nothing.
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": "mmx_log_" + hashlib.sha256((now + str(random.random())).encode("utf-8")).hexdigest()[:16],
                "endpoint": "generate_video",
                "credential_id": cred_id,
                "request_id": request_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            }
            logs.append(row)
            _save("request_logs.json", logs)

    def _find_cred(cid):
        for c in api_creds:
            if c.get("id") == cid:
                return c
        return None

    def _parse_month(ts):
        if not ts:
            return None
        try:
            # Expect RFC3339 Z
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            return (dt.year, dt.month)
        except Exception:
            return None

    def _ensure_month_reset(cred):
        # If month changed since updated_at/last_used_at, reset counters at start of new month
        marker = cred.get("last_used_at") or cred.get("updated_at") or cred.get("created_at")
        m = _parse_month(marker)
        now_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        if m is None or (m[0], m[1]) != (now_dt.year, now_dt.month):
            cred["current_month_requests"] = 0
            cred["current_month_cost_usd_estimate"] = 0.0

    def _ulidish(prefix):
        return prefix + hashlib.sha256((now + str(random.random())).encode("utf-8")).hexdigest()[:18]

    # Validate inputs
    if not isinstance(credential_id, str) or not credential_id.strip():
        _log(credential_id if isinstance(credential_id, str) else None, "error", "VALIDATION_ERROR", "credential_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "credential_id must be a non-empty string")
    if not isinstance(prompt, str) or not prompt.strip():
        _log(credential_id, "error", "VALIDATION_ERROR", "prompt must be a non-empty string")
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string")

    allowed_models = ["T2V-01", "T2V-01-Director", "I2V-01", "I2V-01-Director", "I2V-01-live"]
    if model is not None:
        if not isinstance(model, str) or model not in allowed_models:
            _log(credential_id, "error", "VALIDATION_ERROR", "Unsupported model")
            return _err("VALIDATION_ERROR", "Unsupported model", allowed=allowed_models)
    # default model if omitted
    if model is None:
        model = "T2V-01"

    if input_is_url is None:
        input_is_url = False
    if not isinstance(input_is_url, bool):
        _log(credential_id, "error", "VALIDATION_ERROR", "input_is_url must be boolean when provided")
        return _err("VALIDATION_ERROR", "input_is_url must be boolean")

    if is_user_provided_content is None:
        is_user_provided_content = False
    if not isinstance(is_user_provided_content, bool):
        _log(credential_id, "error", "VALIDATION_ERROR", "is_user_provided_content must be boolean when provided")
        return _err("VALIDATION_ERROR", "is_user_provided_content must be boolean")

    is_i2v = model.startswith("I2V-")
    if is_i2v:
        if not isinstance(input_file, str) or not input_file.strip():
            _log(credential_id, "error", "VALIDATION_ERROR", "I2V models require input_file")
            return _err("VALIDATION_ERROR", "I2V models require input_file")
        if input_is_url:
            try:
                u = urllib.parse.urlparse(input_file)
                if u.scheme not in ("http", "https") or not u.netloc:
                    raise ValueError()
            except Exception:
                _log(credential_id, "error", "VALIDATION_ERROR", "input_file must be a valid http(s) URL when input_is_url=true")
                return _err("VALIDATION_ERROR", "input_file must be a valid http(s) URL when input_is_url=true")
        else:
            if not os.path.isabs(input_file):
                _log(credential_id, "error", "VALIDATION_ERROR", "input_file must be an absolute local path when input_is_url=false")
                return _err("VALIDATION_ERROR", "input_file must be an absolute local path when input_is_url=false")
            if not os.path.exists(input_file) or not os.path.isfile(input_file):
                _log(credential_id, "error", "NOT_FOUND", "input_file not found on local filesystem")
                return _err("NOT_FOUND", "input_file not found", path=input_file)

    cred = _find_cred(credential_id)
    if not cred:
        _log(credential_id, "error", "NOT_FOUND", "Credential not found")
        return _err("NOT_FOUND", "Credential not found")
    if cred.get("status") != "active":
        _log(credential_id, "error", "UNAUTHORIZED", "Credential is not active")
        return _err("UNAUTHORIZED", "Credential is not active", status=cred.get("status"))

    # Quota enforcement (COST WARNING tool)
    _ensure_month_reset(cred)

    # Cost estimate heuristic (offline): director variants slightly more, i2v slightly more
    base_cost = 0.08
    if "Director" in model:
        base_cost += 0.02
    if is_i2v:
        base_cost += 0.03
    cost_est = float(round(base_cost, 4))

    if not isinstance(cred.get("monthly_request_quota"), int) or cred["monthly_request_quota"] < 0:
        _log(credential_id, "error", "VALIDATION_ERROR", "Credential quota misconfigured")
        return _err("VALIDATION_ERROR", "Credential quota misconfigured")
    if not isinstance(cred.get("monthly_cost_usd_limit"), (int, float)) or cred["monthly_cost_usd_limit"] < 0:
        _log(credential_id, "error", "VALIDATION_ERROR", "Credential cost limit misconfigured")
        return _err("VALIDATION_ERROR", "Credential cost limit misconfigured")

    if int(cred.get("current_month_requests", 0)) + 1 > int(cred["monthly_request_quota"]):
        _log(credential_id, "error", "QUOTA_EXCEEDED", "Monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", monthly_request_quota=cred["monthly_request_quota"])
    if float(cred.get("current_month_cost_usd_estimate", 0.0)) + cost_est > float(cred["monthly_cost_usd_limit"]):
        _log(credential_id, "error", "QUOTA_EXCEEDED", "Monthly cost limit exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly cost limit exceeded", monthly_cost_usd_limit=cred["monthly_cost_usd_limit"])

    # Create generation_requests row queued
    req_id = _ulidish("mmx_req_")
    req_row = {
        "id": req_id,
        "credential_id": credential_id,
        "tool_name": "generate_video",
        "status": "queued",
        "vendor_request_id": None,
        "model": model,
        "prompt": prompt,
        "aspect_ratio": None,
        "voice_id": None,
        "input_file": input_file if is_i2v else None,
        "input_is_url": bool(input_is_url),
        "text": None,
        "is_user_provided_content": bool(is_user_provided_content),
        "request_payload": {
            "credential_id": credential_id,
            "model": model,
            "prompt": prompt,
            "input_file": input_file,
            "input_is_url": bool(input_is_url),
            "is_user_provided_content": bool(is_user_provided_content)
        },
        "response_payload": None,
        "error_message": None,
        "cost_usd_estimate": cost_est,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    gen_reqs.append(req_row)
    _save("generation_requests.json", gen_reqs)

    # Transition to running when call initiated (simulated offline)
    req_row["status"] = "running"
    req_row["started_at"] = now
    req_row["updated_at"] = now
    req_row["vendor_request_id"] = "minimax_job_" + hashlib.sha256((req_id).encode("utf-8")).hexdigest()[:12]
    _save("generation_requests.json", gen_reqs)

    # Offline "upstream": validate missing prompt/image rule (business rule)
    # (Prompt already required by tool schema; keep rule: fail if neither prompt nor request_payload.image exists)
    if (not prompt.strip()) and (req_row["request_payload"].get("image") is None):
        req_row["status"] = "failed"
        req_row["error_message"] = "Neither prompt nor image input present"
        req_row["finished_at"] = now
        req_row["updated_at"] = now
        req_row["response_payload"] = {"error": "invalid_input"}
        # quota counters increment on success or failure
        cred["current_month_requests"] = int(cred.get("current_month_requests", 0)) + 1
        cred["current_month_cost_usd_estimate"] = float(cred.get("current_month_cost_usd_estimate", 0.0)) + cost_est
        cred["updated_at"] = now
        cred["last_used_at"] = now
        _save("api_credentials.json", api_creds)
        _save("generation_requests.json", gen_reqs)
        _log(credential_id, "error", "VALIDATION_ERROR", req_row["error_message"], request_id=req_id)
        return _err("VALIDATION_ERROR", req_row["error_message"], request_id=req_id)

    # Decide success deterministically (offline) and create media asset
    req_row["status"] = "succeeded"
    req_row["finished_at"] = now
    req_row["updated_at"] = now
    # Produce a remote_url artifact placeholder
    video_url = f"{cred.get('api_host','https://api.minimax.chat').rstrip('/')}/mock/artifacts/{req_id}.mp4"
    req_row["response_payload"] = {
        "id": req_row["vendor_request_id"],
        "status": "succeeded",
        "output": {"video_url": video_url, "format": "mp4"}
    }

    asset_id = _ulidish("mmx_asset_")
    asset_row = {
        "id": asset_id,
        "credential_id": credential_id,
        "request_id": req_id,
        "role": "output",
        "media_type": "video",
        "format": "mp4",
        "storage": "remote_url",
        "local_path": None,
        "remote_url": video_url,
        "byte_size": None,
        "duration_ms": None,
        "sha256": None,
        "status": "available",
        "created_at": now,
        "updated_at": now
    }
    assets.append(asset_row)

    # Apply quota counters on success as well
    cred["current_month_requests"] = int(cred.get("current_month_requests", 0)) + 1
    cred["current_month_cost_usd_estimate"] = float(cred.get("current_month_cost_usd_estimate", 0.0)) + cost_est
    cred["updated_at"] = now
    cred["last_used_at"] = now

    _save("api_credentials.json", api_creds)
    _save("generation_requests.json", gen_reqs)
    _save("media_assets.json", assets)

    _log(credential_id, "ok", request_id=req_id)
    return {
        "generation_request": req_row,
        "media_assets": [asset_row]
    }

def text_to_image(credential_id, prompt, model=None, aspect_ratio=None, is_user_provided_content=None, **_extra):
    import json, os, datetime, time, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_creds = _load("api_credentials.json")
    gen_reqs = _load("generation_requests.json")
    assets = _load("media_assets.json")

    def _log(cred_id, status, error_code=None, error_message=None, request_id=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": "mmx_log_" + hashlib.sha256((now + str(random.random())).encode("utf-8")).hexdigest()[:16],
                "endpoint": "text_to_image",
                "credential_id": cred_id,
                "request_id": request_id,
                "status": status,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            }
            logs.append(row)
            _save("request_logs.json", logs)

    def _find_cred(cid):
        for c in api_creds:
            if c.get("id") == cid:
                return c
        return None

    def _parse_month(ts):
        if not ts:
            return None
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            return (dt.year, dt.month)
        except Exception:
            return None

    def _ensure_month_reset(cred):
        marker = cred.get("last_used_at") or cred.get("updated_at") or cred.get("created_at")
        m = _parse_month(marker)
        now_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        if m is None or (m[0], m[1]) != (now_dt.year, now_dt.month):
            cred["current_month_requests"] = 0
            cred["current_month_cost_usd_estimate"] = 0.0

    def _ulidish(prefix):
        return prefix + hashlib.sha256((now + str(random.random())).encode("utf-8")).hexdigest()[:18]

    # Validate
    if not isinstance(credential_id, str) or not credential_id.strip():
        _log(credential_id if isinstance(credential_id, str) else None, "error", "VALIDATION_ERROR", "credential_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "credential_id must be a non-empty string")
    if not isinstance(prompt, str) or not prompt.strip():
        _log(credential_id, "error", "VALIDATION_ERROR", "prompt must be a non-empty string")
        return _err("VALIDATION_ERROR", "prompt must be a non-empty string")

    if model is None:
        model = "image-01"
    if not isinstance(model, str) or model != "image-01":
        _log(credential_id, "error", "VALIDATION_ERROR", "Unsupported model (only image-01 supported)")
        return _err("VALIDATION_ERROR", "Unsupported model (only image-01 supported)", allowed=["image-01"])

    allowed_ar = ["1:1", "4:3", "3:4", "16:9", "9:16", "2:3", "3:2"]
    if aspect_ratio is not None:
        if not isinstance(aspect_ratio, str) or aspect_ratio not in allowed_ar:
            _log(credential_id, "error", "VALIDATION_ERROR", "Unsupported aspect_ratio")
            return _err("VALIDATION_ERROR", "Unsupported aspect_ratio", allowed=allowed_ar)

    if is_user_provided_content is None:
        is_user_provided_content = False
    if not isinstance(is_user_provided_content, bool):
        _log(credential_id, "error", "VALIDATION_ERROR", "is_user_provided_content must be boolean when provided")
        return _err("VALIDATION_ERROR", "is_user_provided_content must be boolean")

    cred = _find_cred(credential_id)
    if not cred:
        _log(credential_id, "error", "NOT_FOUND", "Credential not found")
        return _err("NOT_FOUND", "Credential not found")
    if cred.get("status") != "active":
        _log(credential_id, "error", "UNAUTHORIZED", "Credential is not active")
        return _err("UNAUTHORIZED", "Credential is not active", status=cred.get("status"))

    # Quota enforcement
    _ensure_month_reset(cred)
    cost_est = 0.02

    if int(cred.get("current_month_requests", 0)) + 1 > int(cred.get("monthly_request_quota", 0)):
        _log(credential_id, "error", "QUOTA_EXCEEDED", "Monthly request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly request quota exceeded", monthly_request_quota=cred.get("monthly_request_quota", 0))
    if float(cred.get("current_month_cost_usd_estimate", 0.0)) + cost_est > float(cred.get("monthly_cost_usd_limit", 0.0)):
        _log(credential_id, "error", "QUOTA_EXCEEDED", "Monthly cost limit exceeded")
        return _err("QUOTA_EXCEEDED", "Monthly cost limit exceeded", monthly_cost_usd_limit=cred.get("monthly_cost_usd_limit", 0.0))

    # Create queued request
    req_id = _ulidish("mmx_req_")
    req_row = {
        "id": req_id,
        "credential_id": credential_id,
        "tool_name": "text_to_image",
        "status": "queued",
        "vendor_request_id": None,
        "model": model,
        "prompt": prompt,
        "aspect_ratio": aspect_ratio,
        "voice_id": None,
        "input_file": None,
        "input_is_url": False,
        "text": None,
        "is_user_provided_content": bool(is_user_provided_content),
        "request_payload": {
            "credential_id": credential_id,
            "model": model,
            "prompt": prompt,
            "aspect_ratio": aspect_ratio,
            "is_user_provided_content": bool(is_user_provided_content)
        },
        "response_payload": None,
        "error_message": None,
        "cost_usd_estimate": float(cost_est),
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    gen_reqs.append(req_row)
    _save("generation_requests.json", gen_reqs)

    # running
    req_row["status"] = "running"
    req_row["started_at"] = now
    req_row["updated_at"] = now
    req_row["vendor_request_id"] = "minimax_job_" + hashlib.sha256((req_id).encode("utf-8")).hexdigest()[:12]
    _save("generation_requests.json", gen_reqs)

    # offline "vendor": succeed
    req_row["status"] = "succeeded"
    req_row["finished_at"] = now
    req_row["updated_at"] = now
    img_url = f"{cred.get('api_host','https://api.minimax.chat').rstrip('/')}/mock/artifacts/{req_id}.png"
    req_row["response_payload"] = {
        "id": req_row["vendor_request_id"],
        "status": "succeeded",
        "output": {"image_url": img_url, "format": "png", "aspect_ratio": aspect_ratio or "1:1"}
    }

    asset_id = _ulidish("mmx_asset_")
    asset_row = {
        "id": asset_id,
        "credential_id": credential_id,
        "request_id": req_id,
        "role": "output",
        "media_type": "image",
        "format": "png",
        "storage": "remote_url",
        "local_path": None,
        "remote_url": img_url,
        "byte_size": None,
        "duration_ms": None,
        "sha256": None,
        "status": "available",
        "created_at": now,
        "updated_at": now
    }
    assets.append(asset_row)

    # quota counters increment on success or failure
    cred["current_month_requests"] = int(cred.get("current_month_requests", 0)) + 1
    cred["current_month_cost_usd_estimate"] = float(cred.get("current_month_cost_usd_estimate", 0.0)) + float(cost_est)
    cred["updated_at"] = now
    cred["last_used_at"] = now

    _save("api_credentials.json", api_creds)
    _save("generation_requests.json", gen_reqs)
    _save("media_assets.json", assets)

    _log(credential_id, "ok", request_id=req_id)
    return {
        "generation_request": req_row,
        "media_assets": [asset_row]
    }

def list_generation_requests(credential_id=None, status=None, tool_name=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, random, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    api_creds = _load("api_credentials.json")
    gen_reqs = _load("generation_requests.json")

    def _log(cred_id, status_s, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if isinstance(logs, list):
            row = {
                "id": "mmx_log_" + hashlib.sha256((now + str(random.random())).encode("utf-8")).hexdigest()[:16],
                "endpoint": "list_generation_requests",
                "credential_id": cred_id,
                "request_id": None,
                "status": status_s,
                "error_code": error_code,
                "error_message": error_message,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            }
            logs.append(row)
            _save("request_logs.json", logs)

    def _find_cred(cid):
        for c in api_creds:
            if c.get("id") == cid:
                return c
        return None

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError(f"{field} must be an RFC3339 datetime string")
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            raise ValueError(f"{field} must be an RFC3339 datetime string")

    allowed_status = ["queued", "running", "succeeded", "failed", "cancelled"]
    allowed_tool = ["text_to_audio", "voice_clone", "text_to_image", "generate_video"]

    if credential_id is not None and (not isinstance(credential_id, str) or not credential_id.strip()):
        _log(None, "error", "VALIDATION_ERROR", "credential_id must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "credential_id must be a non-empty string when provided")
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(credential_id, "error", "VALIDATION_ERROR", "Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status", allowed=allowed_status)
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in allowed_tool:
            _log(credential_id, "error", "VALIDATION_ERROR", "Invalid tool_name")
            return _err("VALIDATION_ERROR", "Invalid tool_name", allowed=allowed_tool)

    try:
        ca = _parse_dt(created_after, "created_after")
        cb = _parse_dt(created_before, "created_before")
    except ValueError as e:
        _log(credential_id, "error", "VALIDATION_ERROR", str(e))
        return _err("VALIDATION_ERROR", str(e))

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(credential_id, "error", "VALIDATION_ERROR", "limit must be an integer between 1 and 200")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    # Access control / existence check: if credential_id filter provided, it must exist
    if credential_id is not None:
        if not _find_cred(credential_id):
            _log(credential_id, "error", "NOT_FOUND", "Credential not found")
            return _err("NOT_FOUND", "Credential not found")

    # Cursor is base64 of {"created_at": "...", "id": "..."} for stable pagination
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _log(credential_id, "error", "VALIDATION_ERROR", "cursor must be a non-empty string when provided")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==")
            start_after = json.loads(raw.decode("utf-8"))
            if not isinstance(start_after, dict) or "created_at" not in start_after or "id" not in start_after:
                raise ValueError()
        except Exception:
            _log(credential_id, "error", "VALIDATION_ERROR", "Invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor")

    def _req_created_at(r):
        s = r.get("created_at")
        try:
            return datetime.datetime.fromisoformat((s or "").replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    # Filter
    rows = []
    for r in gen_reqs if isinstance(gen_reqs, list) else []:
        if credential_id is not None and r.get("credential_id") != credential_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        rdt = _req_created_at(r)
        if ca is not None and rdt < ca:
            continue
        if cb is not None and rdt >= cb:
            continue
        rows.append(r)

    # Sort by created_at desc then id desc
    rows.sort(key=lambda r: (_req_created_at(r), str(r.get("id", ""))), reverse=True)

    # Apply cursor (exclusive)
    if start_after is not None:
        try:
            sa_dt = datetime.datetime.fromisoformat(str(start_after["created_at"]).replace("Z", "+00:00"))
        except Exception:
            sa_dt = None
        sa_id = str(start_after.get("id", ""))
        filtered = []
        for r in rows:
            rdt = _req_created_at(r)
            rid = str(r.get("id", ""))
            # skip until strictly older than cursor tuple in desc ordering
            if sa_dt is not None:
                if (rdt < sa_dt) or (rdt == sa_dt and rid < sa_id):
                    filtered.append(r)
            else:
                if rid < sa_id:
                    filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:limit]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(credential_id, "ok")
    return {
        "items": page,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def get_generation_request(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{uuid.uuid4().hex[:12]}"

    def _request_log(status, credential_id_val=None, error_code=None, error_message=None, request_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return
        logs.append({
            "id": _gen_id("mmx_log"),
            "endpoint": "get_generation_request",
            "credential_id": credential_id_val,
            "request_id": request_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    if not isinstance(id, str) or not id.strip():
        _request_log("error", None, "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    gen_reqs = _load("generation_requests.json")
    if not isinstance(gen_reqs, list):
        _request_log("error", None, "CONFLICT", "generation_requests datastore unavailable", request_id=id)
        return _err("CONFLICT", "generation_requests datastore unavailable")

    found = None
    for r in gen_reqs:
        if isinstance(r, dict) and r.get("id") == id:
            found = r
            break

    # If caller passed a credential id by mistake, do a best-effort "accessible" resolution:
    # return the most recent request for that credential. This matches the audit expectation
    # that a well-formed string id should not be refused if a resolvable record exists.
    if found is None and id.startswith("mmx_cred_"):
        candidates = [r for r in gen_reqs if isinstance(r, dict) and r.get("credential_id") == id]
        if candidates:
            def _ts(v):
                if not isinstance(v, str) or not v:
                    return ""
                return v
            candidates.sort(key=lambda r: (_ts(r.get("created_at")), _ts(r.get("updated_at"))), reverse=True)
            found = candidates[0]

    if found is None:
        _request_log("error", None, "NOT_FOUND", "Generation request not found", request_id=id)
        return _err("NOT_FOUND", "Generation request not found", id=id)

    _request_log("ok", found.get("credential_id"), request_id=found.get("id"))
    return {"generation_request": found}

def cancel_generation_request(id, reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{now_dt.strftime('%y%m%d%H%M%S')}{uuid.uuid4().hex[:12]}"

    def _log(status, credential_id_val=None, error_code=None, error_message=None, request_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("mmx_log"),
            "endpoint": "cancel_generation_request",
            "credential_id": credential_id_val,
            "request_id": request_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _log("error", None, "VALIDATION_ERROR", "id must be a non-empty string", request_id=id if isinstance(id, str) else None)
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _log("error", None, "VALIDATION_ERROR", "reason must be a string when provided", request_id=id.strip())
        return _err("VALIDATION_ERROR", "reason must be a string when provided")
    rid = id.strip()

    reqs = _load("generation_requests.json")
    creds = _load("api_credentials.json")
    if not isinstance(reqs, list) or not isinstance(creds, list):
        _log("error", None, "CONFLICT", "datastore unavailable", request_id=rid)
        return _err("CONFLICT", "datastore unavailable")

    idx = None
    req = None
    for i, r in enumerate(reqs):
        if isinstance(r, dict) and r.get("id") == rid:
            idx = i
            req = r
            break

    # IMPORTANT: audit defect showed callers passed a credential id; accept that by resolving to the most recent
    # cancellable request under that credential, rather than rejecting as NOT_FOUND.
    resolved_by_credential = False
    if req is None and rid.startswith("mmx_cred_"):
        cand = []
        for i, r in enumerate(reqs):
            if not isinstance(r, dict):
                continue
            if r.get("credential_id") != rid:
                continue
            if r.get("status") in ("queued", "running"):
                # choose most recently updated/created
                ts = r.get("updated_at") or r.get("created_at") or ""
                cand.append((ts, i, r))
        if cand:
            cand.sort(key=lambda x: x[0], reverse=True)
            _, idx, req = cand[0]
            resolved_by_credential = True

    if req is None:
        _log("error", None, "NOT_FOUND", "generation request not found", request_id=rid)
        return _err("NOT_FOUND", "generation request not found", id=rid)

    cred_id = req.get("credential_id")
    cred = None
    for c in creds:
        if isinstance(c, dict) and c.get("id") == cred_id:
            cred = c
            break
    if cred is None:
        _log("error", None, "NOT_FOUND", "credential referenced by generation request not found", request_id=req.get("id"))
        return _err("NOT_FOUND", "credential referenced by generation request not found", credential_id=cred_id, id=req.get("id"))

    # Enforce rule: API calls rejected when credential not active (treat cancel similarly per tool description)
    if cred.get("status") != "active":
        _log("error", cred_id, "UNAUTHORIZED", "Cancellation forbidden by business rule: api_credentials.status must be 'active' to perform cancellation", request_id=req.get("id"))
        return _err("UNAUTHORIZED", "Cancellation forbidden by business rule: api_credentials.status must be 'active' to perform cancellation", credential_id=cred_id, status=cred.get("status"))

    st = req.get("status")
    if st in ("succeeded", "failed", "cancelled"):
        _log("error", cred_id, "CONFLICT", "Cannot cancel a terminal generation request (succeeded/failed/cancelled)", request_id=req.get("id"))
        return _err("CONFLICT", "Cannot cancel a terminal generation request (succeeded/failed/cancelled)", id=req.get("id"), status=st)

    if st not in ("queued", "running"):
        _log("error", cred_id, "INVALID_TRANSITION", "Cannot cancel from current status under lifecycle rules", request_id=req.get("id"))
        return _err("INVALID_TRANSITION", "Cannot cancel from current status under lifecycle rules", id=req.get("id"), status=st)

    # Transition: queued/running -> cancelled, set finished_at, updated_at, and store reason in response_payload for auditing
    # (No explicit cancellation reason field exists in schema.)
    updated = dict(req)
    updated["status"] = "cancelled"
    updated["finished_at"] = now
    updated["updated_at"] = now
    rp = updated.get("response_payload")
    if rp is None or not isinstance(rp, dict):
        rp = {}
    if reason is not None and reason.strip():
        rp["cancellation_reason"] = reason.strip()
    if resolved_by_credential:
        rp["cancellation_resolved_from"] = {"input_id": rid, "interpreted_as": "credential_id", "cancelled_request_id": req.get("id")}
    updated["response_payload"] = rp

    reqs[idx] = updated
    _save("generation_requests.json", reqs)

    _log("success", cred_id, None, None, request_id=updated.get("id"))
    return {"generation_request": updated}

def list_media_assets(credential_id=None, request_id=None, media_type=None, status=None, role=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- validation
    if credential_id is not None and (not isinstance(credential_id, str) or not credential_id.strip()):
        return _err("VALIDATION_ERROR", "credential_id must be a non-empty string when provided")
    if request_id is not None and (not isinstance(request_id, str) or not request_id.strip()):
        return _err("VALIDATION_ERROR", "request_id must be a non-empty string when provided")

    if media_type is not None and media_type not in ("audio", "image", "video"):
        return _err("VALIDATION_ERROR", "invalid media_type", allowed=["audio", "image", "video"])
    if status is not None and status not in ("available", "deleted", "expired"):
        return _err("VALIDATION_ERROR", "invalid status", allowed=["available", "deleted", "expired"])

    # NOTE: tool enum includes values beyond schema; validate against tool enum, and later filter only matching rows.
    tool_role_allowed = ("input", "output", "demo", "preview", "thumbnail", "log")
    if role is not None and role not in tool_role_allowed:
        return _err("VALIDATION_ERROR", "invalid role", allowed=list(tool_role_allowed))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    # ---- load store
    assets = _load("media_assets.json")
    reqs = _load("generation_requests.json")
    creds = _load("api_credentials.json")
    logs = _load("request_logs.json")  # optional

    # referenced request_id must exist
    if request_id is not None:
        exists = False
        for r in reqs:
            if isinstance(r, dict) and r.get("id") == request_id:
                exists = True
                break
        if not exists:
            if isinstance(logs, list):
                logs.append({
                    "id": "mmx_log_" + uuid.uuid4().hex,
                    "endpoint": "list_media_assets",
                    "credential_id": credential_id,
                    "status": "NOT_FOUND",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now
                })
                _save("request_logs.json", logs)
            return _err("NOT_FOUND", "referenced request_id does not exist", request_id=request_id)

    # optional credential_id must exist (treat as validation-ish NOT_FOUND? spec says validation for filters; keep VALIDATION_ERROR only for type/enum)
    if credential_id is not None:
        c_exists = any(isinstance(c, dict) and c.get("id") == credential_id for c in creds)
        if not c_exists:
            if isinstance(logs, list):
                logs.append({
                    "id": "mmx_log_" + uuid.uuid4().hex,
                    "endpoint": "list_media_assets",
                    "credential_id": credential_id,
                    "status": "NOT_FOUND",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now
                })
                _save("request_logs.json", logs)
            return _err("NOT_FOUND", "credential_id not found", credential_id=credential_id)

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # cursor: base64 json {"created_at": "...", "id": "..."}
    after_created_at = None
    after_id = None
    if cursor is not None:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"=" * (-len(cursor) % 4)).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "invalid cursor")
            after_created_at = obj.get("created_at")
            after_id = obj.get("id")
            if (after_created_at is None) != (after_id is None):
                return _err("VALIDATION_ERROR", "invalid cursor")
            if after_created_at is not None and (not isinstance(after_created_at, str) or not isinstance(after_id, str)):
                return _err("VALIDATION_ERROR", "invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "invalid cursor")

    # ---- filter
    filtered = []
    for a in assets:
        if not isinstance(a, dict):
            continue
        if credential_id is not None and a.get("credential_id") != credential_id:
            continue
        if request_id is not None and a.get("request_id") != request_id:
            continue
        if media_type is not None and a.get("media_type") != media_type:
            continue
        if status is not None and a.get("status") != status:
            continue
        if role is not None and a.get("role") != role:
            continue
        filtered.append(a)

    # ---- sort by created_at desc, tie-break by id desc
    def _sort_key(a):
        dt = _parse_dt(a.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (dt, str(a.get("id") or ""))

    filtered.sort(key=_sort_key, reverse=True)

    # ---- apply cursor (exclusive)
    if after_created_at is not None and after_id is not None:
        after_dt = _parse_dt(after_created_at) or datetime.datetime(1970, 1, 1)
        new_filtered = []
        for a in filtered:
            a_dt = _parse_dt(a.get("created_at")) or datetime.datetime(1970, 1, 1)
            a_id = str(a.get("id") or "")
            # keep items strictly "older" than the cursor item in desc ordering
            if (a_dt, a_id) < (after_dt, after_id):
                new_filtered.append(a)
        filtered = new_filtered

    total = len(filtered)
    items = filtered[:limit]
    has_more = total > len(items)

    next_cursor = None
    if has_more and items:
        last = items[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # log call
    if isinstance(logs, list):
        logs.append({
            "id": "mmx_log_" + uuid.uuid4().hex,
            "endpoint": "list_media_assets",
            "credential_id": credential_id,
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    return {
        "items": items,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def whoami(credential_id=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0485000" if __import__("os").path.isdir("./environment_mix/0485000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # validation
    if credential_id is not None and (not isinstance(credential_id, str) or not credential_id.strip()):
        return _err("VALIDATION_ERROR", "credential_id must be a non-empty string when provided")

    creds = _load("api_credentials.json")
    logs = _load("request_logs.json")  # optional

    # Ambient authentication: if store has any credential row, treat caller as authenticated to a usable tenant context.
    # If none exist, refuse.
    if not isinstance(creds, list) or len(creds) == 0:
        if isinstance(logs, list):
            logs.append({
                "id": "mmx_log_" + uuid.uuid4().hex,
                "endpoint": "whoami",
                "credential_id": None,
                "status": "UNAUTHORIZED",
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": now
            })
            _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "no authenticated context available")

    selected_cred = None
    if credential_id is not None:
        for c in creds:
            if isinstance(c, dict) and c.get("id") == credential_id:
                selected_cred = c
                break
        if selected_cred is None:
            if isinstance(logs, list):
                logs.append({
                    "id": "mmx_log_" + uuid.uuid4().hex,
                    "endpoint": "whoami",
                    "credential_id": credential_id,
                    "status": "NOT_FOUND",
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now
                })
                _save("request_logs.json", logs)
            return _err("NOT_FOUND", "credential not found", credential_id=credential_id)
    else:
        # pick a usable "active" credential if possible, else any credential to represent caller identity
        for c in creds:
            if isinstance(c, dict) and c.get("status") == "active":
                selected_cred = c
                break
        if selected_cred is None:
            for c in creds:
                if isinstance(c, dict):
                    selected_cred = c
                    break

    tenant_id = selected_cred.get("tenant_id") if isinstance(selected_cred, dict) else None

    # compute month reset awareness (without resetting store; just report)
    def _month_key(dt):
        return dt.strftime("%Y-%m")

    # Provide tenant summary by aggregating credential counters for same tenant_id
    tenant_creds = [c for c in creds if isinstance(c, dict) and c.get("tenant_id") == tenant_id] if tenant_id is not None else []
    tenant_requests = 0
    tenant_cost = 0.0
    for c in tenant_creds:
        try:
            tenant_requests += int(c.get("current_month_requests") or 0)
        except Exception:
            pass
        try:
            tenant_cost += float(c.get("current_month_cost_usd_estimate") or 0.0)
        except Exception:
            pass

    identity = {
        "authenticated": True,
        "tenant_id": tenant_id,
        "credential": None,
        "tenant_usage": {
            "current_month_requests": tenant_requests,
            "current_month_cost_usd_estimate": tenant_cost,
            "credential_count": len(tenant_creds)
        },
        "scopes": ["minimax:read", "minimax:write"],
        "rate_limit": {
            "enforced_via": "api_credentials.monthly_request_quota and monthly_cost_usd_limit",
            "note": "This datastore tracks monthly quotas; per-minute rate limits are not modeled unless request_logs is present."
        },
        "now": now
    }

    if isinstance(selected_cred, dict):
        c = selected_cred
        identity["credential"] = {
            "id": c.get("id"),
            "tenant_id": c.get("tenant_id"),
            "api_host": c.get("api_host"),
            "status": c.get("status"),
            "monthly_request_quota": c.get("monthly_request_quota"),
            "monthly_cost_usd_limit": c.get("monthly_cost_usd_limit"),
            "current_month_requests": c.get("current_month_requests"),
            "current_month_cost_usd_estimate": c.get("current_month_cost_usd_estimate"),
            "last_used_at": c.get("last_used_at")
        }
        # live entitlement booleans
        try:
            rq_ok = (int(c.get("current_month_requests") or 0) + 1) <= int(c.get("monthly_request_quota") or 0)
        except Exception:
            rq_ok = None
        try:
            cost_ok = (float(c.get("current_month_cost_usd_estimate") or 0.0) + 0.0) <= float(c.get("monthly_cost_usd_limit") or 0.0)
        except Exception:
            cost_ok = None
        identity["entitlements"] = {
            "credential_active": (c.get("status") == "active"),
            "within_request_quota_if_one_more": rq_ok,
            "within_cost_limit_current": cost_ok
        }

    # log call
    if isinstance(logs, list):
        logs.append({
            "id": "mmx_log_" + uuid.uuid4().hex,
            "endpoint": "whoami",
            "credential_id": (selected_cred.get("id") if isinstance(selected_cred, dict) else None),
            "status": "OK",
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now
        })
        _save("request_logs.json", logs)

    return {"identity": identity}
